33	interface Row {
34	  id: string;
35	  name: string;
36	  amount: number;
37	}
38	const ROWS: Row[] = [
39	  { id: "a", name: "Theo", amount: 2100 },
40	  { id: "b", name: "Maya", amount: 2400 },
41	  { id: "c", name: "Omar", amount: 1200 },
42	];
43	const COLUMNS: Column<Row>[] = [
44	  { key: "name", header: "Listener", sortable: true },
45	  {
46	    key: "amount",
47	    header: "Amount",
48	    align: "right",
49	    sortable: true,
50	    render: (r) => `$${(r.amount / 100).toFixed(2)}`,
51	    sortValue: (r) => r.amount,
52	  },
53	];
54	
55	describe("DataTable", () => {
56	  it("renders a semantic table with caption and column headers", async () => {
57	    const { container } = render(
58	      <DataTable
59	        caption="Recent payouts"
60	        columns={COLUMNS}
61	        rows={ROWS}
62	        getRowKey={(r) => r.id}
63	      />,
64	    );
65	    expect(screen.getByRole("table", { name: "Recent payouts" })).toBeInTheDocument();
66	    const headers = screen.getAllByRole("columnheader");
